import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_defects = sum(1 for a in op if a == 'D')
    my_defects = sum(1 for a in my if a == 'D')

    last_my, last_op = history[-1]

    # Fast retaliation against repeated defection, but return to cooperation
    # if opponent has been cooperative recently.
    if n >= 2:
        recent_op = op[-2:]
        recent_opp_defects = sum(1 for a in recent_op if a == 'D')
        if recent_opp_defects >= 2:
            if last_op == 'D':
                return 'D'
            if n >= 4 and sum(1 for a in op[-4:] if a == 'D') >= 3:
                return 'D'

    # If opponent just defected after a long cooperative run, defect once
    # to punish, then resume cooperation unless punished again.
    if last_op == 'D' and last_my == 'C':
        if n == 1:
            return 'D'
        if op[-2] == 'C':
            return 'D'
        # Already in a defection exchange; keep it short.
        if n >= 3 and op[-2] == 'D' and op[-3] == 'D':
            return 'D' if rng.random() < 0.25 else 'C'
        return 'D'

    # If we defected last round and opponent still cooperated, don't exploit
    # too hard; build cooperation.
    if last_my == 'D' and last_op == 'C':
        if opp_defects == 0:
            return 'C'
        if my_defects > opp_defects + 1:
            return 'C'

    # Adaptive: if opponent is generally cooperative, cooperate.
    if opp_defects * 3 <= n:
        return 'C'

    # If opponent is highly defective, use occasional probabilistic defection
    # to avoid being fully exploited, but not pure DD.
    if opp_defects * 2 >= n:
        if last_op == 'D':
            return 'D'
        return 'D' if rng.random() < 0.35 else 'C'

    # Middle ground: mostly cooperate with occasional strategic defection
    # when we are behind in relative payoff potential.
    if last_op == 'C':
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'

